typedef CGAL::Exact_predicates_exact_constructions_kernel Kernel;
typedef Kernel::Point_2 Point_2;
typedef CGAL::Polygon_2<Kernel> Polygon_2;
typedef CGAL::Polygon_with_holes_2<Kernel> Polygon_with_holes_2;
typedef std::list<Polygon_with_holes_2> Pwh_list_2;

Polygon_2 p1, p2;
for (const auto& pt : P1.vertices()) {
    p1.push_back(Point_2(pt.x(), pt.y()));
}
for (const auto& pt : P2.vertices()) {
    p2.push_back(Point_2(pt.x(), pt.y()));
}

Pwh_list_2 union_result;
CGAL::join(p1, p2, std::back_inserter(union_result));

for (const auto& pwh : union_result) {
    std::vector<Point2d> outer_boundary;
    for (auto it = pwh.outer_boundary().vertices_begin(); it != pwh.outer_boundary().vertices_end(); ++it) {
        double x, y;
        internal::getCoordinates(*it, x, y);
        outer_boundary.emplace_back(x, y);
    }
    std::vector<std::vector<Point2d>> holes;
    for (auto it = pwh.holes_begin(); it != pwh.holes_end(); ++it) {
        std::vector<Point2d> hole;
        for (auto hit = it->vertices_begin(); hit != it->vertices_end(); ++hit) {
            double x, y;
            internal::getCoordinates(*hit, x, y);
            hole.emplace_back(x, y);
        }
        holes.emplace_back(hole);
    }
    result.emplace_back(outer_boundary, holes);
}

return result;

